css:
.d-cursor-states{position:relative;width:300px;max-width:100%;height:132px;border:1px solid var(--line);border-radius:10px;background:var(--paper);overflow:hidden;font-family:var(--sans);outline:none;cursor:none;touch-action:none}
.d-cursor-states:focus-visible{outline:1px solid var(--ink);outline-offset:2px}
.d-cs-cursor{position:absolute;left:0;top:0;width:0;height:0;pointer-events:none;opacity:0;transition:opacity 120ms linear}
.d-cursor-states.is-live .d-cs-cursor{opacity:1}
.d-cs-shape{position:absolute;left:0;top:0;display:block;width:8px;height:8px;margin:-4px 0 0 -4px;border:1px solid var(--muted);border-radius:999px;background:transparent;transition:width 120ms steps(6),height 120ms steps(6),margin 120ms steps(6),border-radius 120ms steps(6),border-color 120ms steps(6),background 120ms steps(6)}
.d-cursor-states[data-s=hover] .d-cs-shape{width:16px;height:16px;margin:-8px 0 0 -8px;border-radius:2px;border-color:var(--ink)}
.d-cursor-states[data-s=drag] .d-cs-shape{width:10px;height:10px;margin:-5px 0 0 -5px;border-radius:2px;border-color:var(--ink);background:var(--ink)}
.d-cursor-states[data-s=wait] .d-cs-shape{width:16px;height:16px;margin:-8px 0 0 -8px;border-radius:999px;border-color:var(--line);border-top-color:var(--ink);animation:d-cursor-state-machine-spin 900ms steps(6) infinite}
.d-cs-block{position:absolute;left:28px;top:44px;display:grid;place-items:center;width:64px;height:42px;border:1px solid var(--line);border-radius:6px;background:var(--bg);font-size:var(--fs-11);color:var(--muted);box-shadow:inset 0 1px 0 #fff5;user-select:none}
.d-cursor-states[data-s=drag] .d-cs-block{border-color:var(--ink);color:var(--ink)}
.d-cs-tip{position:absolute;left:10px;bottom:8px;font-family:var(--mono);font-style:normal;font-size:var(--fs-9);letter-spacing:.08em;color:var(--faint)}
@keyframes d-cursor-state-machine-spin{to{transform:rotate(360deg)}}

init:
root => {
  const box = root.querySelector('.d-cursor-states');
  if (!box || box.dataset.dcs) return;
  box.dataset.dcs = '1';
  const cur = box.querySelector('.d-cs-cursor');
  const blk = box.querySelector('.d-cs-block');
  const tip = box.querySelector('.d-cs-tip');
  const label = { idle: '待机', hover: '可抓取', drag: '拖动中', wait: '等待结果' };
  let x = 150, y = 66, drag = false, gx = 0, gy = 0, sx = 0, sy = 0, tx = 0, ty = 0;
  const set = s => { box.dataset.s = s; tip.textContent = label[s]; };
  const hit = () => {
    const a = blk.getBoundingClientRect(), r = box.getBoundingClientRect();
    return x >= a.left - r.left && x <= a.right - r.left && y >= a.top - r.top && y <= a.bottom - r.top;
  };
  const place = (nx, ny) => {
    const r = box.getBoundingClientRect();
    x = Math.max(0, Math.min(r.width, nx));
    y = Math.max(0, Math.min(r.height, ny));
    cur.style.transform = 'translate(' + x + 'px,' + y + 'px)';
    if (!drag) set(hit() ? 'hover' : box.dataset.s === 'wait' ? 'wait' : 'idle');
  };
  const moveBlk = () => {
    const w = box.clientWidth, h = box.clientHeight, bw = blk.offsetWidth, bh = blk.offsetHeight;
    tx = Math.max(-blk.offsetLeft, Math.min(w - blk.offsetLeft - bw, sx + (x - gx)));
    ty = Math.max(-blk.offsetTop, Math.min(h - blk.offsetTop - bh, sy + (y - gy)));
    blk.style.transform = 'translate(' + tx + 'px,' + ty + 'px)';
  };
  const beginDrag = () => { drag = true; gx = x; gy = y; sx = tx; sy = ty; set('drag'); };
  const endDrag = () => {
    drag = false;
    set('wait');
    clearTimeout(box._dcsT);
    box._dcsT = setTimeout(() => set(hit() ? 'hover' : 'idle'), 900);
  };
  box.addEventListener('focus', () => { box.classList.add('is-live'); place(x, y); });
  box.addEventListener('blur', () => { box.classList.remove('is-live'); });
  box.addEventListener('pointerenter', e => {
    const r = box.getBoundingClientRect();
    box.classList.add('is-live');
    place(e.clientX - r.left, e.clientY - r.top);
  });
  box.addEventListener('pointermove', e => {
    const r = box.getBoundingClientRect();
    place(e.clientX - r.left, e.clientY - r.top);
    if (drag) moveBlk();
  });
  box.addEventListener('pointerdown', e => {
    const r = box.getBoundingClientRect();
    place(e.clientX - r.left, e.clientY - r.top);
    if (hit()) { beginDrag(); box.setPointerCapture(e.pointerId); e.preventDefault(); }
  });
  box.addEventListener('pointerup', () => { if (drag) endDrag(); });
  box.addEventListener('pointerleave', () => { if (!drag) box.classList.remove('is-live'); });
  box.addEventListener('keydown', e => {
    const k = e.key, step = 12;
    if (k === 'ArrowLeft') { e.preventDefault(); place(x - step, y); if (drag) moveBlk(); }
    else if (k === 'ArrowRight') { e.preventDefault(); place(x + step, y); if (drag) moveBlk(); }
    else if (k === 'ArrowUp') { e.preventDefault(); place(x, y - step); if (drag) moveBlk(); }
    else if (k === 'ArrowDown') { e.preventDefault(); place(x, y + step); if (drag) moveBlk(); }
    else if (k === ' ') {
      e.preventDefault();
      if (drag) endDrag();
      else if (hit()) beginDrag();
    }
  });
}
